import { i as enquiries, t as db } from "../../../chunks/db.js";
import { a as getOpeningHours, r as getHero, s as getSettings } from "../../../chunks/content.js";
import { i as superValidate, n as message } from "../../../chunks/client2.js";
import "../../../chunks/dist3.js";
import { t as zod } from "../../../chunks/adapters.js";
import { a as customerEnquiryTemplate, n as adminEnquiryTemplate, s as sendEmail } from "../../../chunks/email.js";
import { z } from "zod/v4";
//#region src/routes/contact/schema.ts
var contactSchema = z.object({
	name: z.string("Your name is required").min(2, "Name is too short").max(255),
	email: z.email("A valid email address is required"),
	phone: z.string().max(32, "Phone number is too long").optional(),
	subject: z.string("Subject is required").min(2, "Subject is too short").max(255),
	message: z.string("Message is required").min(10, "Please tell us a little more"),
	/** Honeypot: bots fill hidden fields, humans never see this one. */
	website: z.string().max(0, "Submission rejected").optional()
});
//#endregion
//#region src/routes/contact/+page.server.ts
/** Address, email and phone come from the shared settings row in the layout. */
var load = async () => {
	const [hero, hours, form] = await Promise.all([
		getHero("contact"),
		getOpeningHours(),
		superValidate(zod(contactSchema))
	]);
	return {
		hero,
		hours,
		form
	};
};
var actions = { contact: async ({ request }) => {
	const form = await superValidate(request, zod(contactSchema));
	if (!form.valid) return message(form, {
		type: "error",
		text: "Please check the form for errors"
	}, { status: 400 });
	const { name, email, phone, subject, message: body, website } = form.data;
	if (website) return message(form, {
		type: "success",
		text: "Thanks — we will be in touch shortly."
	});
	try {
		await db.insert(enquiries).values({
			type: "contact",
			name,
			email,
			phone,
			message: `${subject}\n\n${body}`
		});
	} catch {
		return message(form, {
			type: "error",
			text: "We could not save your message. Please try again."
		}, { status: 500 });
	}
	try {
		const settings = await getSettings();
		const notify = adminEnquiryTemplate({
			type: "contact",
			name,
			email,
			phone,
			message: body
		});
		const receipt = customerEnquiryTemplate(name);
		await Promise.all([settings?.email ? sendEmail(settings.email, notify.subject, notify.html) : void 0, sendEmail(email, receipt.subject, receipt.html)]);
	} catch (err) {
		console.error("Contact form notification failed:", err);
	}
	return message(form, {
		type: "success",
		text: "Thank you — your message has been sent. We will get back to you shortly."
	});
} };
//#endregion
export { actions, load };
